from agents import Agent, Runner, RunConfig
from pydantic import BaseModel
from typing import List
from .codeGenerator import GeneratorOutput
from utils.model_provider import get_model

class MergerOutput(BaseModel):
    Code: str

code_merger_agent = Agent(
    name="Code Reviewer and Merger",
    instructions=(
        "You are a senior Manim developer using manim-community v0.19.0.\n"
        "You are given multiple Scene classes generated by other agents.\n"
        "You must output ONLY valid Python code inside a JSON object matching this schema:\n"
        '{"Code": "<merged python code here>"}\n\n'
        "DO NOT include explanations, thoughts, or reasoning — output ONLY the final JSON.\n\n"
        "Your job is to:\n"
        "1. Merge all Scene classes into a single Scene class called AnimationScene.\n"
        "2. Fix syntax or logic errors.\n"
        "3. Ensure compatibility with manim v0.19.0.\n"
        "4. Maintain consistent style and order of input scenes.\n"
        "5. Return only valid code (no commentary).\n"
    ),
    model="MERGER",
    output_type=MergerOutput,
)

async def merger_wrapper(codes: List[GeneratorOutput]):
    
    code_strings = [output.code for output in codes]
    
    combined_codes = "\n\n".join(code_strings)
    
    final_prompt = f"Combine these Scenes into one single Scene class called AnimationScene: \n{combined_codes}\n"
    
    merger_model = get_model("MERGER")
    
    result = await Runner.run(
        code_merger_agent,
        final_prompt,
        run_config=RunConfig(model=merger_model)
    )
    print("######################################################merger used => output: ", result.context_wrapper.usage.output_tokens," input: ", result.context_wrapper.usage.input_tokens, " across: ", result.context_wrapper.usage.requests, " requests")
    
    return result.final_output.Code 